-- ref_outbox (control; single, cluster)
CREATE TABLE [orbit].[ref_outbox] (
  [id] bigint IDENTITY(1,1) NOT NULL,
  [dedupe_key] varchar(512) COLLATE Latin1_General_100_BIN2_UTF8 NOT NULL CHECK (LEN(REPLACE([dedupe_key], ' ', '.')) <= 128),
  [channel] varchar(256) COLLATE Latin1_General_100_BIN2_UTF8 NOT NULL CHECK (LEN(REPLACE([channel], ' ', '.')) <= 64),
  [state] varchar(64) COLLATE Latin1_General_100_BIN2_UTF8 NOT NULL DEFAULT 'pending' CHECK (LEN(REPLACE([state], ' ', '.')) <= 16),
  [attempts] bigint NOT NULL DEFAULT 0,
  [next_at] bigint NOT NULL,
  [payload] varchar(max) NOT NULL CHECK (ISJSON([payload]) = 1),
  [secret] varbinary(max),
  [weight] float,
  [enabled] bit NOT NULL DEFAULT 1,
  [rule] varchar(256) COLLATE Latin1_General_100_BIN2_UTF8 CHECK (LEN(REPLACE([rule], ' ', '.')) <= 64),
  CONSTRAINT [ref_outbox_pkey] PRIMARY KEY CLUSTERED ([id])
);
CREATE UNIQUE NONCLUSTERED INDEX [ref_outbox_dedupe_key_key] ON [orbit].[ref_outbox] ([dedupe_key]) WITH (IGNORE_DUP_KEY = ON);
CREATE NONCLUSTERED INDEX [ref_outbox_due] ON [orbit].[ref_outbox] ([state], [next_at] DESC) WHERE [state] = 'pending';
CREATE NONCLUSTERED INDEX [ref_outbox_channel_idx] ON [orbit].[ref_outbox] ([channel]) WHERE [weight] IS NOT NULL AND [enabled] = 1;

-- ref_rollup (series; single)
CREATE TABLE [orbit].[ref_rollup] (
  [series_id] bigint NOT NULL,
  [bucket] bigint NOT NULL,
  [min] float NOT NULL,
  [max] float NOT NULL,
  [sum] float NOT NULL,
  [count] bigint NOT NULL,
  [last] float,
  CONSTRAINT [ref_rollup_pkey] PRIMARY KEY CLUSTERED ([series_id], [bucket])
);

-- ref_names (state; single, cluster)
CREATE TABLE [orbit].[ref_names] (
  [key] varchar(900) COLLATE Latin1_General_100_BIN2_UTF8 NOT NULL CHECK (LEN(REPLACE([key], ' ', '.')) <= 225),
  [user] varchar(256) CHECK (LEN(REPLACE([user], ' ', '.')) <= 64),
  [note] varchar(max) NOT NULL,
  CONSTRAINT [ref_names_pkey] PRIMARY KEY CLUSTERED ([key]) WITH (IGNORE_DUP_KEY = ON)
);

-- ref_head (series; cluster)
CREATE TABLE [orbit].[ref_head] (
  [shard] bigint NOT NULL,
  [target_id] bigint NOT NULL,
  [slot] bigint NOT NULL,
  [status] bigint NOT NULL,
  [vals] varbinary(max) NOT NULL,
  CONSTRAINT [ref_head_pkey] PRIMARY KEY CLUSTERED ([shard], [target_id], [slot])
) ON [ref_head_ps] ([slot]) /* hour ranges: the partition manager */;
